const p1 = { tag: "v1" };
const p2 = { tag: "v2" };
const item = Object.create(p1);
console.log(item.tag);
Object.setPrototypeOf(item, p2);
console.log(item.tag);
Object.setPrototypeOf(item, null);
console.log(item.tag);
try {
  Object.setPrototypeOf(p1, Object.create(p1));
} catch (err) {
  console.log(err.name);
}
